namespace sv_018afaa7482048eab425ef262b354c14.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// In Blazor Server, "scoped" = per circuit, so each user gets independent state.
/// </summary>
public sealed class ThemeService : IDisposable
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Fired whenever Theme or AccentColor changes.
    /// Interactive components subscribe to this to re-render.
    /// </summary>
    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();

    public void Dispose() => OnChange = null;
}

@* Interactive island placed in the static layout — survives enhanced nav *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService
@inject IJSRuntime JS

<span class="theme-indicator badge" style="background-color: @ThemeService.AccentColor;">
    @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await ApplyThemeToDocument();
        }
    }

    private async void HandleThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            await ApplyThemeToDocument();
            StateHasChanged();
        });
    }

    private async Task ApplyThemeToDocument()
    {
        var themeName = ThemeService.Theme.ToString().ToLowerInvariant();
        await JS.InvokeVoidAsync("document.documentElement.setAttribute", "data-theme", themeName);
        await JS.InvokeVoidAsync("eval",
            $"document.documentElement.style.setProperty('--accent-color', '{ThemeService.AccentColor}')");
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" @bind="SelectedTheme">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <option value="@mode">@mode</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           value="@ThemeService.AccentColor"
           @onchange="OnAccentChanged" />
</div>

<p class="text-muted">
    Current: <strong>@ThemeService.Theme</strong> / <span style="color:@ThemeService.AccentColor">@ThemeService.AccentColor</span>
</p>

@code {
    private ThemeMode SelectedTheme
    {
        get => ThemeService.Theme;
        set => ThemeService.Theme = value;
    }

    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

